import org.json.JSONObject;
public final class PrecisionTextMetricsContract { private PrecisionTextMetricsContract(){} public static JSONObject json() throws Exception {return new JSONObject().put("width",true).put("height",true).put("font_size",true).put("ascent",true).put("descent",true).put("leading",true).put("baseline",true).put("measurement_is_advisory",true);} }
